// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address _distributor) public {
        // Ensure the distributor is not the zero address (to avoid trivial case)
        vm.assume(_distributor != address(0));
        // Set rewardDistributor to a known address
        c.setRewardDistributor(_distributor);
        // Call addReward with any address (should not affect rewardDistributor)
        vm.assume(address(c) != _distributor);
        // Actually call addReward with some random token address
        // We need an address that is not zero and not already in rewardTokens (just use a dummy)
        address dummyToken = address(0x123);
        c.addReward(dummyToken);
        // After addReward, rewardDistributor must still be _distributor
        assertTrue(c.rewardDistributor() == _distributor);
    }
}

